import { useState, useEffect, useRef, useCallback } from "react";
import { Link } from "react-router-dom";
import {
  Leaf,
  LayoutDashboard,
  Radio,
  Droplets,
  CloudSun,
  BarChart3,
  Zap,
  Brain,
  Bell,
  Settings,
  LogOut,
  ChevronRight,
  TrendingUp,
  TrendingDown,
  AlertTriangle,
  Info,
  XCircle,
  Play,
  Pause,
  Clock,
  Calendar,
  Send,
  Sprout,
  Wheat,
  Corn,
  Flower2,
} from "lucide-react";
import { Button } from "../components/ui/button";
import { Input } from "../components/ui/input";
import { toast } from "sonner";

// Color system as CSS variables
const colors = {
  greenDark: "#1e3a2f",
  greenMid: "#2d5a3d",
  greenAccent: "#3a6b4a",
  greenLight: "#4a8a5a",
  terracotta: "#c96a4a",
  terracottaLight: "#d4795c",
  cream: "#f0ece4",
  creamDark: "#e8e3d8",
  gold: "#c8a84b",
  goldLight: "#e8c86b",
  blue: "#3a7ab5",
  blueLight: "#5a9ad5",
  red: "#c94a3a",
  textDark: "#1a2820",
  textMid: "#4a5548",
  textLight: "#8a9488",
  bodyBg: "#f5f2ec",
};

// Initial sensor data
const initialSensorData = {
  soilMoisture: 62,
  temperature: 28,
  humidity: 74,
  soilPh: 6.8,
  ec: 1.8,
  light: 850,
};

// AI responses
const aiResponses = {
  irrigat: "Based on current soil moisture levels (**62%**), I recommend **moderate irrigation** for the next 2 hours. Zone B needs more attention with only 48% moisture.",
  fertiliz: "For wheat crops, apply **Nitrogen-rich fertilizer** (120kg/ha) during the tillering stage. Current soil N levels are **Good** but P is **Low** - consider phosphate supplementation.",
  onion: "Onion prices at Pune APMC are trending **up** (₹1,850/quintal). Consider selling within the next **3-5 days** for optimal returns. Solapur market shows even better rates.",
  ph: "Zone B pH is at **6.2** (slightly acidic). For optimal wheat growth, aim for **6.5-7.0**. Apply agricultural lime (2-3 tons/ha) to raise pH levels gradually.",
  predict: "7-day forecast shows **favorable conditions** for irrigation on Tue-Thu. Expect light rainfall on Saturday (35% probability). Plan irrigation accordingly to reduce water usage.",
  default: "I'm monitoring your farm data in real-time. Current soil moisture is **{moisture}%**, temperature **{temp}°C**, and humidity **{hum}%**. How can I assist you today?",
};

export default function Dashboard() {
  const [userData, setUserData] = useState({
    name: "Ravi Kumar",
    email: "ravi@farm.com",
    state: "Maharashtra",
    city: "Pune",
    landSize: "2.5",
  });
  const [activePage, setActivePage] = useState("dashboard");
  const [sensorData, setSensorData] = useState(initialSensorData);
  const [pumps, setPumps] = useState({
    pump1: { on: true, runtime: 145, schedule: { on: "06:00", off: "08:00", flow: "12L/min" } },
    pump2: { on: false, runtime: 0, schedule: { on: "17:00", off: "19:00", flow: "10L/min" } },
  });
  const [apiLogs, setApiLogs] = useState([]);
  const [telemetryPacket, setTelemetryPacket] = useState({});
  const [weatherData, setWeatherData] = useState(null);
  const [chatMessages, setChatMessages] = useState([]);
  const [chatInput, setChatInput] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(true);
  const [scheduledTimers, setScheduledTimers] = useState({
    pump1: [],
    pump2: [],
  });
  const [showTimerModal, setShowTimerModal] = useState({ show: false, pump: null });
  const [newTimer, setNewTimer] = useState({ startTime: "", duration: "", days: [] });
  const logContainerRef = useRef(null);
  const chatContainerRef = useRef(null);

  // Page configurations
  const pageConfig = {
    dashboard: { title: "Dashboard", subtitle: "Farm overview and insights" },
    sensors: { title: "Sensors", subtitle: "Live sensor data and readings" },
    pump: { title: "Pump Control", subtitle: "Irrigation management" },
    weather: { title: "Weather", subtitle: "Forecast and conditions" },
    market: { title: "Market Prices", subtitle: "Mandi rates and trends" },
    flow: { title: "System Flow", subtitle: "Data pipeline visualization" },
    ai: { title: "AI Assistant", subtitle: "Smart farming recommendations" },
  };

  // Random walk function for sensor simulation
  const randomWalk = useCallback((value, min, max, step) => {
    const change = (Math.random() - 0.5) * step * 2;
    return Math.max(min, Math.min(max, value + change));
  }, []);

  // Update sensor data every 4 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      setSensorData((prev) => ({
        soilMoisture: Math.round(randomWalk(prev.soilMoisture, 40, 85, 3)),
        temperature: Math.round(randomWalk(prev.temperature, 20, 38, 1)),
        humidity: Math.round(randomWalk(prev.humidity, 50, 90, 2)),
        soilPh: parseFloat(randomWalk(prev.soilPh, 5.5, 8.0, 0.1).toFixed(1)),
        ec: parseFloat(randomWalk(prev.ec, 1.0, 3.0, 0.1).toFixed(1)),
        light: Math.round(randomWalk(prev.light, 400, 1200, 50)),
      }));
    }, 4000);
    return () => clearInterval(interval);
  }, [randomWalk]);

  // Update telemetry packet when sensor data changes
  useEffect(() => {
    setTelemetryPacket({
      timestamp: new Date().toISOString(),
      node_id: "sim-node-1",
      soil_moisture: sensorData.soilMoisture,
      temperature: sensorData.temperature,
      humidity: sensorData.humidity,
      ph_level: sensorData.soilPh,
      ec_level: sensorData.ec,
      light_level: sensorData.light,
    });
  }, [sensorData]);

  // API log simulation
  useEffect(() => {
    const endpoints = [
      { method: "GET", path: "/api/sensors/live", status: 200 },
      { method: "POST", path: "/api/telemetry/ingest", status: 201 },
      { method: "GET", path: "/api/weather/forecast", status: 200 },
      { method: "PUT", path: "/api/pump/state", status: 200 },
      { method: "GET", path: "/api/market/prices", status: 200 },
      { method: "GET", path: "/api/alerts/pending", status: 200 },
    ];
    let index = 0;
    const interval = setInterval(() => {
      const endpoint = endpoints[index % endpoints.length];
      const log = {
        id: Date.now(),
        timestamp: new Date().toISOString(),
        method: endpoint.method,
        path: endpoint.path,
        status: endpoint.status,
      };
      setApiLogs((prev) => {
        const updated = [...prev, log];
        return updated.slice(-12);
      });
      index++;
    }, 3500);
    return () => clearInterval(interval);
  }, []);

  // Auto-scroll API log
  useEffect(() => {
    if (logContainerRef.current) {
      logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
    }
  }, [apiLogs]);

  // Check scheduled timers
  useEffect(() => {
    const checkTimers = () => {
      const now = new Date();
      const currentTime = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;
      const currentDay = now.getDay();

      Object.entries(scheduledTimers).forEach(([pumpId, timers]) => {
        timers.forEach((timer) => {
          if (timer.days.includes(currentDay) && timer.startTime === currentTime && !pumps[pumpId].on) {
            togglePump(pumpId);
            toast.success(`${pumpId === "pump1" ? "Pump 1" : "Pump 2"} started by scheduled timer!`);
          }
        });
      });
    };

    const interval = setInterval(checkTimers, 60000); // Check every minute
    return () => clearInterval(interval);
  }, [scheduledTimers, pumps]);

  const togglePump = (pumpId) => {
    setPumps((prev) => ({
      ...prev,
      [pumpId]: {
        ...prev[pumpId],
        on: !prev[pumpId].on,
        runtime: prev[pumpId].on ? prev[pumpId].runtime : 0,
      },
    }));
    toast.success(`${pumpId === "pump1" ? "Pump 1" : "Pump 2"} turned ${pumps[pumpId].on ? "OFF" : "ON"}`);
  };

  const handleSendMessage = () => {
    if (!chatInput.trim()) return;

    const userMessage = { id: Date.now(), type: "user", text: chatInput };
    setChatMessages((prev) => [...prev, userMessage]);
    setChatInput("");
    setShowSuggestions(false);
    setIsTyping(true);

    // AI response logic
    setTimeout(() => {
      const input = chatInput.toLowerCase();
      let responseKey = "default";

      for (const [key, phrase] of Object.entries(aiResponses)) {
        if (key !== "default" && input.includes(key)) {
          responseKey = key;
          break;
        }
      }

      let responseText = aiResponses[responseKey];
      if (responseKey === "default") {
        responseText = responseText
          .replace("{moisture}", sensorData.soilMoisture)
          .replace("{temp}", sensorData.temperature)
          .replace("{hum}", sensorData.humidity);
      }

      // Convert markdown bold to HTML
      responseText = responseText.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");

      setChatMessages((prev) => [
        ...prev,
        { id: Date.now() + 1, type: "bot", text: responseText },
      ]);
      setIsTyping(false);
    }, 1000 + Math.random() * 800);
  };

  const handleSuggestionClick = (suggestion) => {
    setChatInput(suggestion);
    handleSendMessage();
  };

  const handleAddTimer = () => {
    if (!showTimerModal.pump || !newTimer.startTime || !newTimer.duration) {
      toast.error("Please fill in all fields");
      return;
    }

    setScheduledTimers((prev) => ({
      ...prev,
      [showTimerModal.pump]: [
        ...prev[showTimerModal.pump],
        {
          id: Date.now(),
          startTime: newTimer.startTime,
          duration: newTimer.duration,
          days: newTimer.days.length > 0 ? newTimer.days : [0, 1, 2, 3, 4, 5, 6],
        },
      ],
    }));

    setShowTimerModal({ show: false, pump: null });
    setNewTimer({ startTime: "", duration: "", days: [] });
    toast.success("Timer scheduled successfully!");
  };

  const removeTimer = (pumpId, timerId) => {
    setScheduledTimers((prev) => ({
      ...prev,
      [pumpId]: prev[pumpId].filter((t) => t.id !== timerId),
    }));
    toast.success("Timer removed");
  };

  const formatTime = (minutes) => {
    const hrs = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hrs}h ${mins}m`;
  };

  const navItems = [
    { id: "dashboard", icon: LayoutDashboard, label: "Dashboard" },
    { id: "sensors", icon: Radio, label: "Sensors", badge: "Live" },
    { id: "pump", icon: Droplets, label: "Pump Control" },
    { id: "weather", icon: CloudSun, label: "Weather" },
    { id: "market", icon: BarChart3, label: "Market Prices" },
    { id: "flow", icon: Zap, label: "System Flow" },
    { id: "ai", icon: Brain, label: "AI Assistant", badge: "New" },
  ];

  const suggestionChips = [
    "When should I irrigate?",
    "Fertilizer recommendations for wheat",
    "Should I sell onions now?",
    "pH level in Zone B",
    "7-day weather prediction",
  ];

  // Render mini bar chart
  const MiniBarChart = ({ color, data = 12 }) => {
    const bars = Array.from({ length: data }, () => Math.random() * 100);
    return (
      <div className="flex items-end gap-[2px] h-8">
        {bars.map((h, i) => (
          <div
            key={i}
            className="flex-1 rounded-sm"
            style={{
              height: `${Math.max(10, h)}%`,
              background: color,
              opacity: 0.3 + (i / bars.length) * 0.7,
            }}
          />
        ))}
      </div>
    );
  };

  // Render line chart
  const LineChart = ({ data, color, gradient, height = 120 }) => {
    const max = Math.max(...data);
    const min = Math.min(...data);
    const range = max - min || 1;
    const points = data.map((v, i) => ({
      x: (i / (data.length - 1)) * 100,
      y: 100 - ((v - min) / range) * 80 - 10,
    }));
    const pathD = points.map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`).join(" ");
    const areaD = `${pathD} L 100 100 L 0 100 Z`;

    return (
      <svg viewBox="0 0 100 100" className="w-full" style={{ height }} preserveAspectRatio="none">
        <defs>
          <linearGradient id={`gradient-${color}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={color} stopOpacity="0.3" />
            <stop offset="100%" stopColor={color} stopOpacity="0.05" />
          </linearGradient>
        </defs>
        <path d={areaD} fill={`url(#gradient-${color})`} />
        <path d={pathD} fill="none" stroke={color} strokeWidth="2" vectorEffect="non-scaling-stroke" />
      </svg>
    );
  };

  // Render semicircle gauge
  const SemicircleGauge = ({ value, max = 100, size = 140 }) => {
    const radius = size / 2 - 8;
    const circumference = Math.PI * radius;
    const offset = circumference - (value / max) * circumference;

    return (
      <div className="relative inline-block" style={{ width: size, height: size / 2 }}>
        <svg width={size} height={size / 2} viewBox={`0 0 ${size} ${size / 2}`}>
          <defs>
            <linearGradient id="gaugeGradient" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor={colors.red} />
              <stop offset="50%" stopColor={colors.gold} />
              <stop offset="100%" stopColor={colors.greenLight} />
            </linearGradient>
          </defs>
          <path
            d={`M 8 ${size / 2} A ${radius} ${radius} 0 0 1 ${size - 8} ${size / 2}`}
            fill="none"
            stroke={colors.creamDark}
            strokeWidth="8"
          />
          <path
            d={`M 8 ${size / 2} A ${radius} ${radius} 0 0 1 ${size - 8} ${size / 2}`}
            fill="none"
            stroke="url(#gaugeGradient)"
            strokeWidth="8"
            strokeDasharray={circumference}
            strokeDashoffset={offset}
            strokeLinecap="round"
          />
        </svg>
        <div className="absolute bottom-1 left-1/2 -translate-x-1/2 text-center">
          <span className="text-2xl font-mono font-bold" style={{ color: colors.textDark }}>
            {value}
          </span>
          <span className="text-xs" style={{ color: colors.textLight }}>
            /{max}
          </span>
        </div>
      </div>
    );
  };

  // Status chip component
  const StatusChip = ({ status }) => {
    const styles = {
      OK: { bg: "bg-green-100", text: "text-green-700", border: "border-green-200" },
      WARN: { bg: "bg-amber-100", text: "text-amber-700", border: "border-amber-200" },
      CRIT: { bg: "bg-red-100", text: "text-red-700", border: "border-red-200" },
    };
    const s = styles[status] || styles.OK;
    return (
      <span className={`px-2 py-0.5 text-xs font-medium rounded-full border ${s.bg} ${s.text} ${s.border}`}>
        {status}
      </span>
    );
  };

  // Metric card component
  const MetricCard = ({ icon: Icon, title, value, unit, color, trend, trendValue, progress }) => {
    const colorStyles = {
      green: { bg: "bg-green-50", border: "border-green-200", text: "text-green-600", fill: colors.greenLight },
      orange: { bg: "bg-orange-50", border: "border-orange-200", text: "text-orange-600", fill: colors.terracotta },
      blue: { bg: "bg-blue-50", border: "border-blue-200", text: "text-blue-600", fill: colors.blue },
      gold: { bg: "bg-amber-50", border: "border-amber-200", text: "text-amber-600", fill: colors.gold },
    };
    const style = colorStyles[color] || colorStyles.green;

    return (
      <div className={`relative p-4 rounded-xl bg-white border ${style.border} shadow-sm overflow-hidden`}>
        <div
          className="absolute -right-4 -top-4 w-16 h-16 rounded-full opacity-8"
          style={{ background: style.fill }}
        />
        <div className="flex items-start justify-between">
          <div className={`p-2 rounded-lg ${style.bg}`}>
            <Icon className="w-5 h-5" style={{ color: style.fill }} />
          </div>
          {trend && (
            <div className={`flex items-center gap-1 text-xs ${trend === "up" ? "text-green-600" : "text-red-600"}`}>
              {trend === "up" ? <TrendingUp className="w-3 h-3" /> : <TrendingDown className="w-3 h-3" />}
              {trendValue}
            </div>
          )}
        </div>
        <div className="mt-3">
          <p className="text-sm" style={{ color: colors.textLight }}>
            {title}
          </p>
          <p className="text-2xl font-mono font-bold mt-1" style={{ color: colors.textDark }}>
            {value}
            <span className="text-sm font-normal ml-1" style={{ color: colors.textLight }}>
              {unit}
            </span>
          </p>
        </div>
        {progress !== undefined && (
          <div className="mt-3 h-1.5 rounded-full bg-gray-100 overflow-hidden">
            <div
              className="h-full rounded-full transition-all duration-500"
              style={{ width: `${progress}%`, background: style.fill }}
            />
          </div>
        )}
      </div>
    );
  };

  // Sensor card component
  const SensorCard = ({ icon: Icon, title, value, unit, color, min, max, barValue }) => {
    const colorStyles = {
      green: colors.greenLight,
      orange: colors.terracotta,
      blue: colors.blue,
      gold: colors.gold,
      purple: "#8b5cf6",
      amber: colors.goldLight,
    };
    const fill = colorStyles[color] || colors.greenLight;

    return (
      <div className="p-4 rounded-xl bg-white border border-[#e8e3d8] shadow-sm">
        <div className="flex items-center gap-2 mb-3">
          <div className="p-1.5 rounded-lg" style={{ background: `${fill}20` }}>
            <Icon className="w-4 h-4" style={{ color: fill }} />
          </div>
          <span className="text-sm font-medium" style={{ color: colors.textDark }}>
            {title}
          </span>
        </div>
        <p className="text-3xl font-mono font-bold" style={{ color: colors.textDark }}>
          {value}
          <span className="text-base font-normal ml-1" style={{ color: colors.textLight }}>
            {unit}
          </span>
        </p>
        <div className="mt-3">
          <div className="flex justify-between text-xs mb-1" style={{ color: colors.textLight }}>
            <span>{min}</span>
            <span>{max}</span>
          </div>
          <div className="h-2 rounded-full bg-gray-100 overflow-hidden">
            <div
              className="h-full rounded-full transition-all duration-500"
              style={{ width: `${barValue}%`, background: `linear-gradient(90deg, ${fill}, ${fill}80)` }}
            />
          </div>
        </div>
        <div className="mt-3">
          <MiniBarChart color={fill} />
        </div>
      </div>
    );
  };

  // Pump card component
  const PumpCard = ({ id, name, zone, pump }) => {
    return (
      <div className="p-5 rounded-xl bg-white border border-[#e8e3d8] shadow-sm">
        <div className="flex items-start justify-between mb-4">
          <div>
            <h3 className="font-semibold" style={{ color: colors.textDark }}>
              {name}
            </h3>
            <p className="text-sm" style={{ color: colors.textLight }}>
              {zone}
            </p>
          </div>
          <button
            onClick={() => togglePump(id)}
            className={`relative w-12 h-6 rounded-full transition-colors ${pump.on ? "bg-green-500" : "bg-gray-300"}`}
          >
            <div
              className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow transition-transform ${
                pump.on ? "translate-x-7" : "translate-x-1"
              }`}
            />
          </button>
        </div>

        <div className="flex items-center gap-4 mb-4">
          <div
            className={`w-16 h-16 rounded-full flex items-center justify-center transition-all ${
              pump.on
                ? "bg-green-50 animate-pulse"
                : "bg-gray-100"
            }`}
            style={
              pump.on
                ? { boxShadow: `0 0 20px ${colors.greenLight}40` }
                : {}
            }
          >
            {pump.on ? (
              <Droplets className="w-6 h-6 animate-spin" style={{ color: colors.greenLight, animationDuration: "3s" }} />
            ) : (
              <span className="text-2xl">⏸️</span>
            )}
          </div>
          <div>
            <p className="text-sm" style={{ color: colors.textLight }}>
              Status
            </p>
            <p className="font-medium" style={{ color: colors.textDark }}>
              {pump.on ? "Running" : "Stopped"}
            </p>
            {pump.on && (
              <p className="text-sm" style={{ color: colors.greenLight }}>
                Runtime: {formatTime(pump.runtime)}
              </p>
            )}
          </div>
        </div>

        <div className="flex gap-2 mb-4">
          <span className="px-2 py-1 text-xs rounded-md bg-gray-100" style={{ color: colors.textMid }}>
            ON: {pump.schedule.on}
          </span>
          <span className="px-2 py-1 text-xs rounded-md bg-gray-100" style={{ color: colors.textMid }}>
            OFF: {pump.schedule.off}
          </span>
          <span className="px-2 py-1 text-xs rounded-md bg-gray-100" style={{ color: colors.textMid }}>
            {pump.schedule.flow}
          </span>
        </div>

        <div className="h-2 rounded-full bg-gray-100 overflow-hidden mb-3">
          <div
            className="h-full rounded-full transition-all duration-500"
            style={{
              width: pump.on ? "65%" : "0%",
              background: `linear-gradient(90deg, ${colors.greenLight}, ${colors.greenAccent})`,
            }}
          />
        </div>

        <p className="text-xs text-center" style={{ color: colors.textLight }}>
          Auto Mode Active
        </p>

        {/* Scheduled Timers */}
        <div className="mt-4 pt-4 border-t border-gray-100">
          <div className="flex items-center justify-between mb-2">
            <p className="text-sm font-medium" style={{ color: colors.textDark }}>
